head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Source 탭 또는 Property 탭 에서 expr 의 importExp 를 확인한다. 
    //1. Check the importExp of expr in the Source tab or Property tab.
    //Verify 1. importExp='"테스트"
    //Test step 2. 브라우저에서 expr 컬럼 (상품명2항목의 컬럼) 부분을 확인한다. 
    //2. In the browser, check the expr column (column of item 2 column).
    //Verify 2. 정상적으로 importExp 적용되서 '테스트' 가 표시된다. (그전버전에서는 표시되지 않음.)
    //2. Normally importExp is applied and 'Test' is displayed. (Not shown in previous versions.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').textContent == '테스트'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_1_1').textContent == '테스트'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_2_1').textContent == '테스트'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.data = [{
            "col1": "삼림빵",
            "col2": 2,
            "col3": 3,
            "col4": 4,
            "rowStatus": "R"
        },
        {
            "col1": "마늘빵",
            "col2": 6,
            "col3": 2,
            "col4": 8,
            "rowStatus": "R"
        },
        {
            "col1": "모카빵",
            "col2": 5,
            "col3": 1,
            "col4": 2,
            "rowStatus": "R"
        }
    ];
    dataList1.setJSON(data); // setJSON에서도 importExp 사용할 수 있음(WP-2091)
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 08-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
